  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Recibimos su recibo, gracias 🌱 Nos comunicaremos con usted sobre su pago lo antes posible.',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => 'Recibimos tu recibo, gracias 🌱 Tu donación está confirmada.',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Ya habíamos recibido este recibo, gracias 🌱 Nos comunicaremos con usted sobre su pago lo antes posible.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'Este recibo parece haber sido cargado en nuestro sistema anteriormente. No se puede utilizar el mismo recibo para una segunda donación. Si realizó un pago diferente, envíe ese recibo; nuestro equipo también lo comprobará.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'Recibimos su recibo. El monto que contiene (%1$s) no parece coincidir con el monto de su donación (%2$s). ¿Podrías comprobarlo? Si realizaste un pago diferente, puedes escribir aquí; nuestro equipo también echará un vistazo.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'Recibimos su recibo, pero el destinatario que figura en él no parece ser nuestra asociación. Las donaciones sólo se realizan a nuestra cuenta a nombre de "%s". ¿Podrías comprobarlo? Nuestro equipo también echará un vistazo.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'Recibimos su recibo, pero el destinatario que figura en él no parece coincidir con nuestra cuenta. ¿Podrías comprobarlo? Nuestro equipo también echará un vistazo.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'El archivo que envió no parece un recibo de pago. Si has pagado, puedes enviar el recibo o una captura de pantalla de la pantalla de pago aquí.',
