  '+ New report' => '+ Nuevo informe',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'El número del destinatario proviene de Usuarios › Perfil › Número de WhatsApp; permisos de Usuarios › Roles y acceso (recibir informes, ver informe general, administrar informes). Los informes salen a la hora elegida; sin un programador de servidor, se envían en la siguiente visita al sitio o en el uso del panel de chat.',
  'Invalid phone number.' => 'Número de teléfono no válido.',
  'First add a WhatsApp connection under Settings › Connections.' => 'Primero agregue una conexión de WhatsApp en Configuración>Conexiones.',
  '%1$s assigned the chat to %2$s' => '%1$sasignó el chat a%2$s',
