  'You can only delete your own notes.' => 'Sólo puedes eliminar tus propias notas.',
  'Reply text cannot be empty.' => 'El texto de respuesta no puede estar vacío.',
  'Connection not found. Save the settings first.' => 'Conexión no encontrada. Guarde la configuración primero.',
  'The message was only image code; it was not sent.' => 'El mensaje era sólo un código de imagen; no fue enviado.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'Este contacto está bloqueado; no se envían mensajes. Elimínelos de la lista de bloqueo para volver a escribir.',
  'Message could not be saved.' => 'No se pudo guardar el mensaje.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Este contacto escribe desde un número oculto de WhatsApp (@lid) y Evolution API (versión%s) no pudo enviar a esta dirección. Actualice el servidor API de Evolution a 2.3 o posterior; si llega el número real del contacto, el complemento lo envía allí.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Este contacto escribe desde un número oculto de WhatsApp (@lid) y Evolution API no pudo enviar a esta dirección. Actualice el servidor API de Evolution a 2.3 o posterior; si llega el número real del contacto, el complemento lo envía allí.',
  'No WhatsApp connection.' => 'Sin conexión WhatsApp.',
  'Connected ✓' => 'Conectado ✓',
  'Not connected (state: %s). Connect with QR.' => 'No conectado (estado:%s). Conéctate con QR.',
  'Webhook points to this site ✓' => 'Webhook apunta a este sitio ✓',
  'Evolution API version: %s' => 'Versión de la API de evolución:%s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(antiguo: las respuestas a contactos con números ocultos (@lid) pueden fallar; actualice a 2.3 o posterior)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'El webhook no apunta a este sitio. Presione "Configurar webhook".',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Configuración del webhook ✓ Los mensajes entrantes ahora llegarán aquí.',
  'Importing recent chats, this may take a while…' => 'Importando chats recientes, esto puede tardar un poco...',
  'Messages stored in Evolution: %s' => 'Mensajes almacenados en Evolution:%s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution no almacena mensajes, por lo que no se pueden cargar mensajes más antiguos. En el servidor Evolution, configure DATABASE_SAVE_DATA_NEW_MESSAGE y DATABASE_SAVE_DATA_HISTORIC en verdadero; para conversaciones más antiguas, mantenga activado "Sincronizar historial completo" en la configuración de la instancia cuando vuelva a conectar la línea con QR.',
  '%1$s chats, %2$s messages imported ✓' => 'Chats%1$s, mensajes%2$simportados ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'Escanea este código vía WhatsApp › Dispositivos vinculados › Vincula un dispositivo.',
  'Pairing code:' => 'Código de emparejamiento:',
  'This line is already connected ✓' => 'Esta línea ya está conectada ✓',
  'Save the settings first.' => 'Guarde la configuración primero.',
  'Error:' => 'Error:',
  'Delete this connection? Chat history is kept.' => '¿Eliminar esta conexión? Se mantiene el historial de chat.',
  'Asking the AI…' => 'Preguntando a la IA...',
  'Working ✓ (%2$s ms): %1$s' => 'Trabajando ✓ (%2$sms):%1$s',
  'Save the key and model first.' => 'Guarde la clave y el modelo primero.',
  'Connections' => 'Conexiones',
  'Auto replies' => 'Respuestas automáticas',
  'AI and assistant' => 'IA y asistente',
  'System check' => 'Verificación del sistema',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'Conecta tu línea de WhatsApp, gestiona respuestas automáticas y etiquetas.',
  'Open chats' => 'abrir chats',
  'Settings saved.' => 'Configuración guardada.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Conexiones y configuraciones que necesita el call center. Se muestra el estado guardado; utilice los botones de "prueba" en cada pestaña para una verificación en vivo. Las mismas comprobaciones también aparecen con los otros complementos en la pantalla de verificación del sistema del tema.',
  'WhatsApp lines' => 'Líneas de whatsapp',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'Los mensajes se envían y reciben a través de Evolution API. Las conexiones de WhatsApp se gestionan en Flux Mail; Elija cuál usar aquí. La URL y la clave API permanecen allí, por lo que no es necesario actualizarlas aquí cuando cambian.',
  'Communication › Connections' => 'Comunicación › Conexiones',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'Los mensajes se envían y reciben a través de Evolution API. Si un proveedor de Evolution está configurado en Certificados Flux, puede elegir la misma conexión; la URL y la clave API permanecen allí.',
  'Add line' => 'Agregar línea',
  'Setup steps' => 'Pasos de configuración',
  'Add the line and save.' => 'Añade la línea y guarda.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'Utilice "Probar conexión" para ver si se puede acceder a Evolution. Si la línea no está vinculada, elige "Conectar con QR" y escanéala desde el teléfono.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'Presione "Configurar webhook". Los mensajes entrantes y los mensajes enviados desde el teléfono y desde los Certificados Flux aparecen aquí en vivo.',
  'Optionally bring in past messages with "Import recent chats".' => 'Opcionalmente, trae mensajes pasados con "Importar chats recientes".',
  'connected' => 'conectado',
  'connecting' => 'conectando',
  'not connected' => 'no conectado',
