  'Flux Mail connection: %s' => 'Conexión de correo Flux:%s',
  'Flux Mail connection #%d (not found or disabled)' => 'Conexión de Flux Mail #%d(no encontrada o deshabilitada)',
  'Use Flux Certificates provider: %s' => 'Utilice el proveedor de certificados Flux:%s',
  'Enter separate Evolution API details' => 'Ingrese detalles separados de la API de Evolution',
  'Line name (e.g. Main line)' => 'Nombre de línea (por ejemplo, línea principal)',
  'Connection details' => 'Detalles de conexión',
  'API URL' => 'URL de la API',
  'Instance name' => 'Nombre de instancia',
  'API key (apikey)' => 'Clave API (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (guardado; escriba para cambiar)',
  'Webhook URL' => 'URL de webhook',
  'Regenerate secret key' => 'Regenerar clave secreta',
  'Last webhook: %s' => 'Último webhook:%s',
  'No webhook received yet.' => 'Aún no se ha recibido ningún webhook.',
  'Test connection' => 'Conexión de prueba',
  'Connect with QR' => 'Conéctate con QR',
  'QR, status and accounts: Communication › Connections' => 'QR, estados y cuentas: Comunicación › Conexiones',
  'Set up webhook' => 'Configurar webhook',
  'Import recent chats' => 'Importar chats recientes',
  'The webhook URL and test buttons appear after saving.' => 'La URL del webhook y los botones de prueba aparecen después de guardar.',
  'Appearance' => 'Apariencia',
  'Panel title' => 'Título del panel',
  'Site name if empty. The {brand} variable uses this too.' => 'Nombre del sitio si está vacío. La variable{brand}también usa esto.',
  'Accent color' => 'Color de acento',
  'Behavior' => 'Comportamiento',
  'Send read receipts (blue ticks) when a chat is opened' => 'Enviar recibos de lectura (marcas azules) cuando se abre un chat',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Mensajes con prefijo con el nombre del agente (*Nombre:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Los agentes ven solo los chats que tienen asignados y los chats no asignados (los administradores ven todos)',
  'Also show WhatsApp group messages' => 'Mostrar también mensajes grupales de WhatsApp',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Nueva interfaz (experimental): la página de Chats se abre con la misma pantalla que la aplicación de escritorio y móvil',
  'Live update interval (sec)' => 'Intervalo de actualización en vivo (seg.)',
  'The open tab checks for new messages at this interval (10 recommended). In a background tab it checks once a minute, and less often after errors.' => 'La pestaña abierta busca mensajes nuevos en este intervalo (se recomiendan 10). En una pestaña en segundo plano, verifica una vez por minuto y con menos frecuencia después de errores.',
  'Agents' => 'Agentes',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Asigne a un usuario el rol%s; solo ven la pantalla de chat y no pueden abrir la configuración. Los administradores siempre tienen acceso.',
  'Add new user' => 'Agregar nuevo usuario',
  'Data' => 'Datos',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'También elimine todos los chats, mensajes y archivos multimedia cuando se elimine el complemento.',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Los archivos multimedia se guardan en wp-content/uploads/flx-chat, cerrados al acceso externo. Se mueven con las cargas cuando se migra el sitio.',
  'Mon' => 'lun',
  'Tue' => 'mar',
  'Wed' => 'mié',
  'Thu' => 'jueves',
  'Fri' => 'viernes',
  'Sat' => 'sábado',
  'Sun' => 'sol',
  'Welcome message' => 'Mensaje de bienvenida',
  'Send automatically to people who write to us for the first time' => 'Enviar automáticamente a las personas que nos escriben por primera vez',
  'Away message' => 'mensaje de ausencia',
  'Auto reply to messages received outside business hours' => 'Respuesta automática a mensajes recibidos fuera del horario comercial',
  'Business days' => 'Días hábiles',
  'Start' => 'Empezar',
  'End' => 'Fin',
  'At most once per contact every (hours)' => 'Como máximo una vez por contacto cada (horas)',
  'Timezone: %1$s. Now: %2$s.' => 'Zona horaria:%1$s. Ahora:%2$s.',
  'within business hours' => 'dentro del horario comercial',
  'outside business hours' => 'fuera del horario comercial',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'En los textos se pueden utilizar las variables{first_name},{name},{brand},{site},{date}.',
  'Chat labels' => 'Etiquetas de chat',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Etiquete los chats y filtre la lista (por ejemplo, Donación, Queja, Seguimiento).',
  'Add label' => 'Agregar etiqueta',
  'Label name' => 'Nombre de la etiqueta',
  'Creating records from chats' => 'Crear registros a partir de chats',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Los botones en el encabezado del chat crean un registro de donación (Flux Donate) y un certificado (Certificados Flux), y un recibo entrante se compara con un registro. Si un complemento no está instalado, su botón está oculto.',
  'Agents can create donation records and match receipts' => 'Los agentes pueden crear registros de donaciones y comparar recibos.',
  'Agents can create and send certificates' => 'Los agentes pueden crear y enviar certificados.',
  'Show quick reply bubbles above the message box' => 'Mostrar burbujas de respuesta rápida encima del cuadro de mensaje',
  'Donation messages' => 'Mensajes de donación',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Textos listos enviados a la persona cuando se crea un registro (editables antes de enviar). Si se deja vacío, se utiliza el texto predeterminado.',
  'Awaiting payment (promised transfer)' => 'En espera de pago (transferencia prometida)',
  'Donation received' => 'Donación recibida',
  'Receipt confirmed' => 'Recibo confirmado',
  'Bank details ({bank})' => 'Datos bancarios ({bank})',
  'Recipient name, bank, IBAN' => 'Nombre del destinatario, banco, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'Si está vacía, se utiliza la cuenta en WooCommerce › Pagos › Transferencia bancaria.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variables:{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'AI connection' => 'Conexión de IA',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Las claves, el almacenamiento en caché de avisos, los límites de gasto y los registros de uso provienen del complemento Flux AI & MCP; todas las solicitudes de IA del Call Center pasan por él. Las opciones de modelos se quedan aquí; si un campo está vacío, se utiliza el modelo elegido para este complemento en Flux AI (o el predeterminado).',
  'Open Flux AI settings' => 'Abrir la configuración de Flux AI',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'La IA necesita el complemento Flux AI y MCP. Instálelo y actívelo, luego ingrese la clave OpenRouter y/o Anthropic en Flux AI & MCP › Configuración. Hasta entonces quedan desactivadas las sugerencias, el asistente, la lectura de recibos, los mensajes de voz y los resúmenes.',
  'Creativity (0–1)' => 'Creatividad (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Los valores más bajos dan respuestas más consistentes, los valores más altos, más libres. 0,4 recomendado.',
  'Model (for suggestions)' => 'Modelo (para sugerencias)',
  'Assistant model (optional)' => 'Modelo asistente (opcional)',
  'Model above' => 'Modelo arriba',
  'Only models that support tools are listed.' => 'Solo se enumeran los modelos que admiten herramientas.',
  'Receipt reading model (optional)' => 'Modelo de lectura de recibos (opcional)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Si el modelo seleccionado no puede leer imágenes, se utiliza automáticamente un modelo de visión económico.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'Este mes (%1$s): solicitudes%2$s, tokens%3$s, alrededor de $%4$s.',
  'Reply suggestions' => 'Sugerencias de respuesta',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Encima del cuadro de mensaje, se sugiere el siguiente mensaje de la conversación. El agente hace clic en "Enviar" o lo lleva al cuadro con "Editar". Una sugerencia nunca se envía sola.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Preparar una sugerencia automáticamente cuando llegó el último mensaje de la persona (si está desactivado, pregunta con el botón ✨)',
  'Organization info and tone' => 'Información y tono de la organización.',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'Por ej. Nuestra asociación planta árboles jóvenes en Estambul. La siembra se realiza todos los años entre noviembre y marzo. El certificado se envía por WhatsApp después de la donación. Utilice un tono cálido pero formal.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Las sugerencias y el asistente utilizan esto. Los tipos de donación, precios, datos bancarios y respuestas rápidas se agregan automáticamente.',
  'Suggestion provider' => 'Proveedor de sugerencias',
  'Donation assistant (automatic replies)' => 'Asistente de donaciones (respuestas automáticas)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'Cuando está activado, el asistente se responde a sí mismo: saluda, pregunta el nombre para dirigirse a ellos, envía opciones y precios de donación, opcionalmente recopila correo electrónico y "en nombre de quién", y pide confirmación después de cada cambio. Después de la confirmación, abre un registro "en espera de pago" en Flux Donate y envía el enlace de donación, el destinatario, el IBAN y la referencia como mensajes separados. Si el tema deja donaciones, entrega el chat al equipo.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'El complemento Flux Donate no está activo; el asistente no puede crear registros de donación.',
  'Instructions, documents, AI chats and test chat' => 'Instrucciones, documentos, chats de IA y chat de prueba.',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Active el asistente de donación (desmarque para desactivarlo en todas partes)',
  'Which chats should it reply to' => '¿A qué chats debería responder?',
  'In all chats (recommended)' => 'En todos los chats (recomendado)',
  'In chats not assigned to an agent' => 'En chats no asignados a un agente',
  'Only outside working hours' => 'Sólo fuera del horario laboral',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Cuando un agente escribe en un chat (desde el panel o el teléfono), el asistente se queda ahí callado el tiempo que aparece a continuación. Utilice el botón del asistente en el encabezado del chat para activarlo o desactivarlo por chat.',
  'Test mode: reply only to the numbers below' => 'Modo de prueba: responda solo a los números a continuación',
  'Test numbers' => 'Números de prueba',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Sepárelos con comas o líneas nuevas. No se utiliza cuando el modo de prueba está desactivado.',
  'Quiet after an agent writes (hours)' => 'Silencio después de que un agente escribe (horas)',
  'Quantities in the price list' => 'Cantidades en la lista de precios.',
  'Conversation history (hours)' => 'Historial de conversaciones (horas)',
  'Before replying, the assistant reads all messages from this period.' => 'Antes de responder, el asistente lee todos los mensajes de este período.',
  'Donation types the assistant offers' => 'Tipos de donación que ofrece el asistente',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Si no se selecciona ninguno, se ofrecen todos los tipos abiertos. Cuando se abre un nuevo tipo en Flux Donate, el asistente también lo sabe.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Verificación previa del recibo: cuando el contacto envía un recibo, AI compara el monto, el destinatario y el IBAN con la donación, le informa al contacto el resultado, adjunta el archivo al registro de donación y entrega el chat al equipo para su aprobación final (no lo marca como pagado).',
  'Last line of the price list' => 'Última línea de la lista de precios.',
  'Payment details' => 'Detalles de pago',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Si el destinatario y el IBAN están vacíos, se utilizan los de WooCommerce › Pagos › Transferencia bancaria (la cuenta que se muestra en los pedidos). Rellénelos sólo si el asistente debe usar una cuenta diferente.',
  'Recipient name' => 'Nombre del destinatario',
  'Transfer description' => 'Descripción de la transferencia',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Variables:{type},{name},{amount},{quantity}',
  'Donation page URL' => 'URL de la página de donación',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'El tipo y la cantidad seleccionados se agregan al enlace (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'Mensaje después de los detalles de pago.',
  'Donation cancellation question' => 'Pregunta de cancelación de donación.',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'El asistente cancela únicamente donaciones no pagadas, con la confirmación de la persona. Vacío = texto predeterminado. Variables:{bagis},{tutar}.',
  'Message sent when the daily limit is reached' => 'Mensaje enviado cuando se alcanza el límite diario',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Se envía una vez cuando un chat alcanza el límite de respuestas del día; el chat se entrega al equipo. Restablecerlo desde el menú ⋮ del chat › Uso del asistente.',
  'Message sent when handing over to the team' => 'Mensaje enviado al momento de la entrega al equipo.',
  'Message sent when the assistant cannot answer' => 'Mensaje enviado cuando el asistente no puede responder',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Si la IA falla, se alcanza el límite de tiempo o la cola se vuelve demasiado larga, se envía este mensaje y el chat se entrega al equipo; la persona nunca se queda sin respuesta.',
  'Minimum wait before the holding message (s)' => 'Espera mínima antes del mensaje(s) de espera',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'El mensaje en espera no se envía hasta tantos segundos después del mensaje de la persona; Mientras tanto el asistente vuelve a intentarlo.',
  'Longest time for one answer (s)' => 'Mayor tiempo para una respuesta (s)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger puede reducir las solicitudes en ~60 s; Se recomienda 50.',
  'Numbers notified on handoff' => 'Números notificados en el traspaso',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Cuando el asistente entrega un chat al equipo, desde la misma línea se envía un mensaje de WhatsApp a estos números: nombre del contacto, teléfono, motivo, últimos mensajes y enlace del panel. Sepárelos con comas o líneas nuevas. El asistente no habla con estos números.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Cuando el contacto escribe uno de estos, el asistente envía inmediatamente el mensaje de transferencia anterior y se apaga en ese chat. Si se deja vacío, se utiliza la lista de ejemplo.',
  'Extra instructions for the assistant' => 'Instrucciones adicionales para el asistente.',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'Por ej. Se plantan árboles jóvenes en Kocaeli. Los certificados se envían una vez confirmada la donación.',
  'Last message when a contact opts out' => 'Último mensaje cuando un contacto se da de baja',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Si alguien escribe algo como "no me envíes mensajes", el asistente envía este mensaje y lo incluye en la lista de bloqueo. Una persona incluida en la lista bloqueada no recibe WhatsApp, correo electrónico ni SMS; administre la lista en Chats › ☰ › Lista de bloqueo.',
  'Contact memory and background jobs' => 'Memoria de contacto y trabajos en segundo plano.',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Memoria de contacto: el asistente recuerda detalles duraderos (forma de dirección, nombres de familiares, números, preferencias); Se resumen los chats caducados.',
  'Summarize a chat after it has been quiet for (hours)' => 'Resumir un chat después de que haya estado en silencio durante (horas)',
  'Maximum jobs at the same time' => 'Máximos trabajos al mismo tiempo',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'A cuántas personas se les puede responder al mismo tiempo. Las respuestas del asistente siempre son lo primero; los resúmenes no comienzan mientras alguien recibe respuesta o espera. Cada trabajo utiliza un trabajador PHP: en alojamiento compartido, manténgase por debajo de la mitad del límite total de trabajadores de sus sitios (por ejemplo, 20-30 de 60 trabajadores).',
  'Workers reserved for replies' => 'Trabajadores reservados para respuestas.',
  'This many workers never take summaries or reminders.' => 'Esta cantidad de trabajadores nunca toma resúmenes ni recordatorios.',
  'Summary hours' => 'Resumen de horas',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Los resúmenes se publican únicamente entre estas horas (excepto un manual "Resumir ahora"). Si ambos son iguales, en cualquier momento.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Cuando alguien envía un mensaje de voz, el asistente lo convierte en texto y responde (el texto también aparece en el panel como una línea del sistema)',
  'Longest voice message (sec)' => 'Mensaje de voz más largo (seg.)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'Para mensajes más largos, el asistente dice "el mensaje de voz fue demasiado largo para que podamos escucharlo".',
  'Voice message model (optional)' => 'Modelo de mensaje de voz (opcional)',
  'Cheap audio model (Gemini Flash Lite)' => 'Modelo de audio económico (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Debe ser un modelo de OpenRouter que acepte audio (Claude no). Se requiere una clave OpenRouter.',
  'Images' => 'Imágenes',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Deje que el asistente dibuje una imagen cuando sea útil (tabla, informe, diagrama); va a WhatsApp como una imagen, el texto se envía por separado',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Se utiliza el renderizador de imágenes Flux AI (Flux AI y MCP › Configuración › Imágenes).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'No hay renderizador de imágenes en el servidor: ingrese una dirección de Gotenberg en Flux AI & MCP › Configuración › Imágenes o instale Imagick (SVG). Hasta entonces el asistente no dibuja imágenes.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Funciona una vez instalado Flux AI 0.2.0 o posterior.',
  'Donation on behalf of someone' => 'Donación en nombre de alguien',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Si la donación está a nombre de otra persona y se le dio su número (tarjeta de contacto o número tecleado), también enviar el certificado a ese número por WhatsApp una vez aprobado el pago.',
  'Message sent before the certificate' => 'Mensaje enviado antes del certificado.',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Luego se envía el mensaje de certificado de WhatsApp de Flux Certificates. Variables:{ad},{bagisci},{bagis},{brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Si una persona pregunta, el asistente configura un recordatorio (por ejemplo, "recuérdame cómo plantar un árbol cada mes", "envíame tus últimos proyectos cada mes", "pídeme un árbol cada mes"); cuando llega el momento, el asistente escribe y envía el mensaje',
  'When no time is given' => 'Cuando no se da tiempo',
  'At most per person' => 'Como máximo por persona',
  'Staff (Flux Roles)' => 'Personal (roles cambiantes)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Funciona una vez instalado Flux Roles 1.1.0: los usuarios cuyo número está configurado en Perfil › Número de WhatsApp obtienen herramientas de asistente adicionales según sus permisos.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Darle al personal herramientas adicionales de asistente mediante permiso (donación en nombre de alguien con enlace de pago, mis donantes, informe general)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Notificar al personal en WhatsApp cuando se paga o cancela una donación que ellos recomendaron.',
  'First message to the donor for a donation opened by staff' => 'Primer mensaje al donante para una donación abierta por el personal',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Hola{ad}🌱 Se recibió tu solicitud de donación{bagis}a través de{personel}. Puedes pagar con los detalles a continuación.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'A continuación se muestran el enlace de pago y los datos bancarios. Variables:{ad},{adsoyad},{personel},{bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Cuando se paga una donación referida por un miembro del personal y se emiten sus certificados, envíalos también al miembro del personal por WhatsApp (al igual que el donante)',
  'Message sent to the staff member before the certificate' => 'Mensaje enviado al miembro del personal antes del certificado.',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variables:{ad},{bagisci},{bagis},{no},{brand}.',
  'How many times staff can resend a donation\'s certificate' => '¿Cuántas veces el personal puede reenviar el certificado de donación?',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'El asistente enumera los destinatarios y solicita confirmación antes de enviar. 0: apagado.',
  'Code verification for record lookups' => 'Verificación de código para búsquedas de registros',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Cuando una persona solicita sus registros y su número está oculto (o donó con otro número/correo electrónico), envíe un código al número o correo electrónico que proporcione; una vez verificado, sus registros también se muestran',
  'Code validity (min)' => 'Validez del código (min)',
  'Maximum failed attempts' => 'Máximo de intentos fallidos',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Se cuentan los códigos que no se pudieron enviar, los códigos incorrectos y los códigos caducados. En el límite, la persona recibe el siguiente mensaje y se notifica al equipo; el asistente sigue respondiendo otras preguntas pero no comparte detalles del registro durante 24 horas.',
  'Code to phone' => 'codigo al telefono',
  'WhatsApp, SMS if it fails' => 'WhatsApp, SMS si falla',
  'WhatsApp only' => 'solo WhatsApp',
  'SMS only' => 'solo SMS',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'Se utiliza SMS si Flux Mail tiene una conexión SMS (por ejemplo, Netgsm).',
  'Message when verification fails' => 'Mensaje cuando falla la verificación',
  'WhatsApp/SMS code message' => 'Mensaje de código WhatsApp/SMS',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'Texto predeterminado si está vacío. Variables:{kod},{dk},{marka}. El texto del correo electrónico se edita en Flux Mail › Plantillas de correo electrónico.',
  'Site content' => 'Contenido del sitio',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Deje que el asistente busque contenido publicado en el sitio (por ejemplo, "¿tiene una publicación sobre plantación de árboles")',
  'Content types to search' => 'Tipos de contenido para buscar',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Sólo se devuelve el contenido publicado sin contraseña. Nunca se muestran borradores, contenido privado y protegido con contraseña.',
  'Categories and tags never to share' => 'Categorías y etiquetas que nunca debes compartir',
  'e.g. corporate-offers, internal-notice' => 'por ej. ofertas-corporativas, aviso-interno',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'Nombre o slug, separados por comas. Para ocultar un solo elemento, marque "No permitir que el asistente comparta este contenido" en su pantalla de edición.',
