  'Based on average token usage of {n} past scenario results; actual cost per scenario may vary.' => 'Basado en el uso promedio de tokens de los resultados de escenarios anteriores{n}; El costo real por escenario puede variar.',
  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'Aún no hay carreras; Estimación predeterminada: ~ tokens de entrada{i}/ salida{o}por mensaje de donante.',
