  'One phrase per line' => 'Una frase por línea',
  'E.g. Should not ask for a name; short and warm greeting.' => 'Por ej. No debería pedir un nombre; Saludo breve y cálido.',
  'One tool name per line; a|b for alternatives' => 'Un nombre de herramienta por línea; a|b para alternativas',
