  'Group' => 'grupo',
  'Messages (in order)' => 'Mensajes (en orden)',
  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => 'Se pueden utilizar{tur},{birim}y{brand}. Si solo hay mensajes de clientes, el asistente responde a cada uno por turno. Si agrega mensajes del asistente, se convierte en un escenario de continuación: el historial escrito se proporciona tal cual y el asistente responde solo al último mensaje del cliente.',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'Por ej. información_pago, cancelar_donación, recibo_cheque. Las herramientas deshabilitadas en este sitio no están marcadas.',
  'Who is writing?' => '¿Quién escribe?',
  'Starting state (test)' => 'Estado inicial (prueba)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'El escenario se ejecuta aislado como el chat de prueba; Lo que seleccione aquí existe sólo en esta prueba. En un mensaje de cliente,{kod}se convierte en el código de verificación del panel de prueba.',
  'End state' => 'Estado final',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'Cuando finaliza la conversación, se comprueba el estado de la prueba (si se abrió una donación, se canceló, se envió un código...). Las herramientas deshabilitadas en este sitio no están marcadas.',
  'Judge criterion' => 'Criterio de juez',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => 'Si está vacío, no se llama al juez. Coloque aquí expectativas de calidad que no se pueden escribir como reglas.',
