  'Media folder' => 'Carpeta multimedia',
  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'No puedo escribir en uploads/flx-chat; Las fotos, notas de voz y documentos entrantes no se pueden guardar. Verifique los permisos de la carpeta.',
  'Folder protection (.htaccess) missing; it is created with the first saved media.' => 'Falta protección de carpeta (.htaccess); se crea con los primeros medios guardados.',
