  'PHP cURL' => 'rizo PHP',
  'Available.' => 'Disponible.',
  'Missing; while the assistant prepares a reply the "typing…" indicator shows only briefly.' => 'Desaparecido; Mientras el asistente prepara una respuesta, el indicador "escribiendo..." se muestra sólo brevemente.',
  'Users with the agent role: %d.' => 'Usuarios con rol de agente:%d.',
  'No user has the agent role; only administrators can use it for now.' => 'Ningún usuario tiene el rol de agente; sólo los administradores pueden usarlo por ahora.',
  'Live panel updates' => 'Actualizaciones del panel en vivo',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (60 s in a background tab).' => 'Última solicitud de actualización%1$s. Mientras el panel está abierto, busca mensajes nuevos cada%2$ds (60 s en una pestaña en segundo plano).',
  'The chat screen has not been opened yet.' => 'La pantalla de chat aún no se ha abierto.',
  'WhatsApp line' => 'línea whatsapp',
  'No line added.' => 'No se agregó ninguna línea.',
  '%s: connection details' => '%s: detalles de conexión',
  'Using Flux Mail connection: %s.' => 'Usando la conexión de Flux Mail:%s.',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Sigo usando el antiguo proveedor en Certificados Flux; mueva la conexión a Flux Mail y selecciónela aquí.',
  'Using the Evolution provider from Flux Certificates.' => 'Utilizando el proveedor Evolution de Flux Certificates.',
  'API URL, key and instance are entered in this plugin.' => 'La URL de API, la clave y la instancia se ingresan en este complemento.',
  '%s: line status' => '%s: estado de la línea',
  'Phone connected (last seen %s).' => 'Teléfono conectado (visto por última vez%s).',
  'Not tested yet. Press "Test connection".' => 'Aún no probado. Pulsa "Probar conexión".',
  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'Teléfono no conectado (estado:%1$s,%2$s). Vuelva a conectarse con "Conectar con QR".',
  '%s: Evolution API version' => '%s: Versión de la API de evolución',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'La API de Evolution%sestá en uso. Las respuestas a contactos con números ocultos (@lid) pueden fallar; actualice el servidor a 2.3 o posterior.',
  '%s: webhook (incoming messages)' => '%s: webhook (mensajes entrantes)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'No han llegado eventos de Evolution; Los mensajes entrantes no se mostrarán en el panel. Presione "Configurar webhook".',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'Llegó el último evento%s. Es posible que la línea esté simplemente en silencio; envíate un mensaje o configura el webhook nuevamente para estar seguro.',
  'Last event arrived %s.' => 'Llegó el último evento%s.',
  'Flux Mail integration' => 'Integración de correo Flux',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'Activo: Las conexiones de WhatsApp se toman desde Comunicación › Conexiones.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail no está activo; las conexiones se toman de Certificados Flux o de este complemento.',
  'Flux Certificates integration' => 'Integración de certificados Flux',
  'Active: certificates can be created and sent from chats.' => 'Activo: se pueden crear y enviar certificados desde los chats.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Los Certificados Flux no están activos; Las acciones de certificado en los chats están desactivadas.',
  'Flux Donate integration' => 'Integración de donaciones de flujo',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'Activo: los registros de donaciones, el cotejo de recibos y el asistente están disponibles desde los chats.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donar no está activo; Los registros de donación, la comparación de recibos y el asistente de donación están desactivados.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'El complemento Flux AI & MCP no está instalado; Las funciones de IA (sugerencias, asistente, lectura de recibos, mensajes de voz, resúmenes) están desactivadas. Instale Flux AI e ingrese la clave allí.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'No se ha ingresado ninguna clave en Flux AI; las sugerencias de mensajes y el asistente están apagados.',
  'Key saved but no model selected.' => 'Clave guardada pero no se seleccionó ningún modelo.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'No se ha ingresado ninguna clave de proveedor en Flux AI para el modelo seleccionado (%s).',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'Clave guardada, modelo:%s. Utilice "Probar conexión" para una verificación en vivo.',
  'Donation assistant' => 'asistente de donación',
  'Off.' => 'Apagado.',
  'AI key or model is missing.' => 'Falta la clave o el modelo de IA.',
  'On but not replying: ' => 'Encendido pero sin responder:',
  'On. Donation types offered: %s.' => 'Encendido. Tipos de donación ofrecidos:%s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%sno admite herramientas; Elija un modelo con capacidad para herramientas para el asistente.',
  'Receipt reading model' => 'Modelo de lectura de recibos',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%sno puede leer imágenes; la verificación previa del recibo no funcionará. Elija un modelo de lectura de recibos con capacidad de imagen.',
  'Assistant payment details' => 'Detalles de pago del asistente',
  'Recipient name and IBAN set.' => 'Nombre del destinatario y conjunto IBAN.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'Falta el nombre del destinatario o el IBAN; Los datos bancarios no se pueden enviar después de la confirmación.',
  'Donation page link' => 'Enlace a la página de donaciones',
  'Donation page not found; the assistant will not send a link.' => 'Página de donación no encontrada; el asistente no enviará un enlace.',
  'Background requests' => 'Solicitudes de antecedentes',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'El sitio no pudo enviarse una solicitud en segundo plano (%1$s:%2$s). Las respuestas en cola y el punto de referencia pueden moverse lentamente; un complemento de seguridad o el firewall del servidor pueden estar bloqueando las solicitudes /wp-json/flx-chat/.',
  'error' => 'error',
  'warning' => 'advertencia',
  'ok' => 'bien',
  'Your {marka} verification code: {kod}' => 'Su código de verificación{marka}:{kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'El código es válido por minutos{dk}. Escríbelo en tu chat de WhatsApp con nosotros. Si no lo solicitaste, ignora este mensaje.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Algo salió mal; nuestro equipo se pondrá en contacto contigo lo antes posible 🌱 Mientras tanto, no dudes en preguntar cualquier otra cosa.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'Intento de verificación fallido (%1$d/%2$d):%3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'La persona quería ver sus registros pero no pudo ser verificada; alguien del equipo debería ponerse en contacto',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'No se pudo enviar el correo electrónico (verifique Flux Mail › Configuración SMTP)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'El asistente envió un código de verificación para%1$s(%2$s).',
  'code expired' => 'código caducado',
  'wrong code' => 'código incorrecto',
  'The person verified the code for %s; it is added to their record lookups.' => 'La persona verificó el código de%s; se agrega a sus búsquedas de registros.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Los modelos Claude no pueden leer audio; elija un modelo OpenRouter con capacidad de audio en Configuración › AI › Modelo de mensaje de voz.',
  'The audio could not be transcribed.' => 'No se pudo transcribir el audio.',
  'The audio file could not be read.' => 'No se pudo leer el archivo de audio.',
  'Voice message (%1$s) transcribed: %2$s' => 'Mensaje de voz (%1$s) transcrito:%2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'No se pudo procesar el mensaje de voz (%1$s):%2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Esta acción no está disponible en una línea API oficial de WhatsApp Cloud.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'Regla de las 24 horas de WhatsApp: el contacto no ha escrito en las últimas 24 horas, por lo que la API de Cloud no enviará un mensaje de formato libre; sólo se puede enviar una plantilla aprobada. Inténtalo de nuevo una vez que escriban.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Una línea API de nube necesita Flux Mail 1.10.0 o posterior.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'La API de la nube no puede enviar a esta dirección (número o grupo oculto).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'No se pudo acceder a la cuenta API de la nube (İletişim › Conexiones).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Una línea de Cloud API no tiene código QR; la cuenta está configurada en İletişim › Conexiones.',
  'The file could not be prepared.' => 'No se pudo preparar el archivo.',
  'Flux AI has no image support.' => 'Flux AI no admite imágenes.',
  'The image could not be rendered.' => 'No se pudo renderizar la imagen.',
  'The assistant\'s image could not be sent: ' => 'No se pudo enviar la imagen del asistente:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Hola{first_name}, hemos creado tu registro de donación:{donation}, total{amount}.{bank}Después de pagar, puedes enviar el recibo aquí. Gracias.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Hola{first_name}, tu donación ha quedado registrada:{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Gracias por su apoyo.',
  'The plugin that would run this scenario is inactive.' => 'El complemento que ejecutaría este escenario está inactivo.',
  'This user is not allowed to use the staff tools.' => 'Este usuario no tiene permiso para utilizar las herramientas del personal.',
  '%1$s linked this chat to staff member %2$s' => '%1$svinculó este chat con el miembro del personal%2$s',
  '%s removed the staff link of this chat' => '%seliminó el enlace del personal de este chat.',
  'Chat linked to staff member' => 'Chat vinculado a un miembro del personal',
  'Staff link removed' => 'Enlace de personal eliminado',
  '— Not staff —' => '— No personal —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp oculta el número de esta persona, por lo que el asistente no puede reconocer al personal por número. Si esta persona está en su equipo, vincúlela aquí y el asistente abrirá las herramientas del personal.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'El asistente reconoce al personal por el número en su perfil de Flux Roles. Si el número no coincide, puedes vincularlos aquí; En un chat con un número conocido, el número es lo primero.',
  'This channel is not available right now.' => 'Este canal no está disponible en este momento.',
  'Site chat' => 'Chat del sitio',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'Todos los mensajes de WhatsApp, chat del sitio y otros canales aparecen aquí en vivo. Elige un chat a la izquierda.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => '[[\'Centro de llamadas de WhatsApp (Evolution API): vea mensajes entrantes y salientes en vivo, inicie un nuevo chat, respuestas predeterminadas, etiquetas, tareas, notas internas, respuestas automáticas; Registro de donación (Flux Donate) y certificado (Flux Certificates) desde el chat, cotejo de recibos. Sugerencia de respuesta de inteligencia artificial y asistente de donación automática con OpenRouter.\', \'tr\']]',
  'Çağrı Merkezi' => 'centro de llamadas',
  'Sohbetler' => 'Charlas',
  'AI asistan' => 'asistente de IA',
  'Çağrı Merkezi Ayarları' => 'Configuración del centro de llamadas',
  'Ayarlar' => 'Configuración',
  'Çağrı Merkezi için JavaScript gerekli.' => 'Se requiere JavaScript para el Call Center.',
  'Bu sayfaya erişim yetkiniz yok.' => 'No tienes permiso para acceder a esta página.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'Supervise los chats que maneja el asistente, edite sus instrucciones y documentos y pruebe los cambios antes de publicarlos.',
  'Asistan ayarları' => 'Configuración del asistente',
  'Bu sayfa için JavaScript gerekli.' => 'Esta página requiere JavaScript.',
  'Kapalı' => 'Cerrado',
  'Açık, 5 dakika' => 'encendido, 5 minutos',
  'Açık, 1 saat' => 'encendido, 1 hora',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'La IA necesita el complemento Flux AI y MCP; instálelo y actívelo, luego ingrese la clave en Flux AI & MCP ›Configuración.',
  'Yapay zekâ modeli seçilmemiş.' => 'No se seleccionó ningún modelo de IA.',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'No se ha ingresado ninguna clave antrópica (Claude) en Flux AI.',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'No se ha ingresado ninguna clave OpenRouter en Flux AI.',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'La lista de modelos necesita el complemento Flux AI & MCP.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Centro de llamadas Flux: las funciones de IA (sugerencias, asistente, lectura de recibos, mensajes de voz, resúmenes) necesitan el complemento Flux AI y MCP. Instálelo y actívelo; Las claves guardadas en el Call Center se mueven allí automáticamente.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux Call Center: una clave%sdiferente ya está guardada en Flux AI y es la que está en uso. La antigua clave del Call Center no se movió y ya no se utiliza.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Centro de llamadas Flux: las claves AI se trasladaron a Flux AI. A partir de ahora, las claves, los límites de gasto y los registros se gestionan en Flux AI; Las opciones de modelos permanecen en el Call Center.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'El complemento Flux Donate no está activo; el asistente toma los tipos de donaciones y los precios.',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'No hay ningún tipo de donación abierto en Flux Donate (abra uno en la página de tipos de donación).',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => 'Los tipos de donación seleccionados para el asistente son cerrados o no tienen precio; seleccione un tipo abierto o deje la selección vacía.',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => 'Ninguno de los tipos de donación abiertos tiene precio (Flux Donate › Tipos de donación › precio de opción).',
