  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => 'Recibimos tu recibo, gracias 🌱 Tu donación está confirmada.',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'Ya habíamos recibido este recibo, gracias 🌱 Nos comunicaremos con usted sobre su pago lo antes posible.',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'Este recibo parece haber sido cargado en nuestro sistema anteriormente. No se puede utilizar el mismo recibo para una segunda donación. Si realizó un pago diferente, envíe ese recibo; nuestro equipo también lo comprobará.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'Recibimos su recibo. El monto que contiene (%1$s) no parece coincidir con el monto de su donación (%2$s). ¿Podrías comprobarlo? Si realizaste un pago diferente, puedes escribir aquí; nuestro equipo también echará un vistazo.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Recibimos su recibo, pero el destinatario que figura en él no parece ser nuestra asociación. Las donaciones sólo se realizan a nuestra cuenta a nombre de "%s". ¿Podrías comprobarlo? Nuestro equipo también echará un vistazo.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Recibimos su recibo, pero el destinatario que figura en él no parece coincidir con nuestra cuenta. ¿Podrías comprobarlo? Nuestro equipo también echará un vistazo.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'El archivo que envió no parece un recibo de pago. Si has pagado, puedes enviar el recibo o una captura de pantalla de la pantalla de pago aquí.',
