  'Bu rapor silinsin mi?' => '¿Eliminar este informe?',
  '+ Yeni rapor' => '+ Nuevo informe',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'El número del destinatario proviene de Usuarios › Perfil › Número de WhatsApp; permisos de Usuarios › Roles y acceso (recibir informes, ver informe general, administrar informes). Los informes salen a la hora elegida; sin un programador de servidor, se envían en la siguiente visita al sitio o en el uso del panel de chat.',
  'Geçersiz telefon numarası.' => 'Número de teléfono no válido.',
  'Önce Ayarlar › Bağlantılar bölümünden bir WhatsApp bağlantısı ekleyin.' => 'Primero agregue una conexión de WhatsApp en Configuración>Conexiones.',
