  'Bu dosya türü gönderilemez.' => 'Este tipo de archivo no se puede enviar.',
  'Dosya yüklenemedi.' => 'No se pudo cargar el archivo.',
  'Bu mesaj yeniden gönderilemez.' => 'Este mensaje no se puede reenviar.',
  'Bu mesaja tepki verilemez.' => 'No puedo reaccionar a este mensaje.',
  'Yalnız kendi notlarınızı silebilirsiniz.' => 'Sólo puedes eliminar tus propias notas.',
  'Cevap metni boş olamaz.' => 'El texto de respuesta no puede estar vacío.',
  'Bağlantı bulunamadı. Önce ayarları kaydedin.' => 'Conexión no encontrada. Guarde la configuración primero.',
  'Mesaj yalnız görsel kodundan oluşuyordu; gönderilmedi.' => 'El mensaje era sólo un código de imagen; no fue enviado.',
  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'Este contacto está bloqueado; no se envían mensajes. Elimínelos de la lista de bloqueo para volver a escribir.',
  'Mesaj kaydedilemedi.' => 'No se pudo guardar el mensaje.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Este contacto escribe desde un número oculto de WhatsApp (@lid) y Evolution API (versión%s) no pudo enviar a esta dirección. Actualice el servidor API de Evolution a 2.3 o posterior; si llega el número real del contacto, el complemento lo envía allí.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Este contacto escribe desde un número oculto de WhatsApp (@lid) y Evolution API no pudo enviar a esta dirección. Actualice el servidor API de Evolution a 2.3 o posterior; si llega el número real del contacto, el complemento lo envía allí.',
  'WhatsApp bağlantısı yok.' => 'Sin conexión WhatsApp.',
  'Bağlı ✓' => 'Conectado ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'No conectado (estado:%s). Conéctate con QR.',
  'Webhook bu siteye ayarlı ✓' => 'Webhook apunta a este sitio ✓',
  'Evolution API sürümü: %s' => 'Versión de la API de evolución:%s',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(antiguo: las respuestas a contactos con números ocultos (@lid) pueden fallar; actualice a 2.3 o posterior)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'El webhook no apunta a este sitio. Presione "Configurar webhook".',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Configuración del webhook ✓ Los mensajes entrantes ahora llegarán aquí.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'Importando chats recientes, esto puede tardar un poco...',
  'Evolution\'da kayıtlı mesaj: %s' => 'Mensajes almacenados en Evolution:%s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution no almacena mensajes, por lo que no se pueden cargar mensajes más antiguos. En el servidor Evolution, configure DATABASE_SAVE_DATA_NEW_MESSAGE y DATABASE_SAVE_DATA_HISTORIC en verdadero; para conversaciones más antiguas, mantenga activado "Sincronizar historial completo" en la configuración de la instancia cuando vuelva a conectar la línea con QR.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => 'Chats%1$s, mensajes%2$simportados ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'Escanea este código vía WhatsApp › Dispositivos vinculados › Vincula un dispositivo.',
  'Eşleştirme kodu:' => 'Código de emparejamiento:',
  'Bu hat zaten bağlı ✓' => 'Esta línea ya está conectada ✓',
  'Önce ayarları kaydedin.' => 'Guarde la configuración primero.',
  'Hata:' => 'Error:',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => '¿Eliminar esta conexión? Se mantiene el historial de chat.',
  'Yapay zekâya soruluyor…' => 'Preguntando a la IA...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => 'Trabajando ✓ (%2$sms):%1$s',
  'Önce anahtarı ve modeli kaydedin.' => 'Guarde la clave y el modelo primero.',
  'Bağlantılar' => 'Conexiones',
  'Otomatik yanıtlar' => 'Respuestas automáticas',
  'Yapay zekâ ve asistan' => 'IA y asistente',
  'Sistem kontrolü' => 'Verificación del sistema',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'Conecta tu línea de WhatsApp, gestiona respuestas automáticas y etiquetas.',
  'Sohbetleri aç' => 'abrir chats',
  'Ayarlar kaydedildi.' => 'Configuración guardada.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'Conexiones y configuraciones que necesita el call center. Se muestra el estado guardado; utilice los botones de "prueba" en cada pestaña para una verificación en vivo. Las mismas comprobaciones también aparecen con los otros complementos en la pantalla de verificación del sistema del tema.',
  'WhatsApp hatları' => 'Líneas de whatsapp',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'Los mensajes se envían y reciben a través de Evolution API. Las conexiones de WhatsApp se gestionan en Flux Mail; Elija cuál usar aquí. La URL y la clave API permanecen allí, por lo que no es necesario actualizarlas aquí cuando cambian.',
  'İletişim › Bağlantılar' => 'Comunicación › Conexiones',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'Los mensajes se envían y reciben a través de Evolution API. Si un proveedor de Evolution está configurado en Certificados Flux, puede elegir la misma conexión; la URL y la clave API permanecen allí.',
  'Hat ekle' => 'Agregar línea',
  'Kurulum adımları' => 'Pasos de configuración',
  'Hattı ekleyip kaydedin.' => 'Añade la línea y guarda.',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => 'Utilice "Probar conexión" para ver si se puede acceder a Evolution. Si la línea no está vinculada, elige "Conectar con QR" y escanéala desde el teléfono.',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'Presione "Configurar webhook". Los mensajes entrantes y los mensajes enviados desde el teléfono y desde los Certificados Flux aparecen aquí en vivo.',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => 'Opcionalmente, trae mensajes pasados con "Importar chats recientes".',
