  'Temsilciler yalnız kendine atanan ve atanmamış sohbetleri görsün (yöneticiler hepsini görür)' => 'Los agentes ven solo los chats que tienen asignados y los chats no asignados (los administradores ven todos)',
  'WhatsApp grup mesajlarını da göster' => 'Mostrar también mensajes grupales de WhatsApp',
  'Yeni arayüz (deneysel): Sohbetler sayfası masaüstü ve mobil uygulamayla aynı ekranla açılır' => 'Nueva interfaz (experimental): la página de Chats se abre con la misma pantalla que la aplicación de escritorio y móvil',
  'Canlı güncelleme sıklığı (sn)' => 'Intervalo de actualización en vivo (seg.)',
  'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10). Sekme arka plandayken dakikada bir, hata olursa giderek seyrekleşir.' => 'La pestaña abierta busca mensajes nuevos en este intervalo (se recomiendan 10). En una pestaña en segundo plano, verifica una vez por minuto y con menos frecuencia después de errores.',
  'Temsilciler' => 'Agentes',
  'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.' => 'Asigne a un usuario el rol%s; solo ven la pantalla de chat y no pueden abrir la configuración. Los administradores siempre tienen acceso.',
  'Yeni kullanıcı ekle' => 'Agregar nuevo usuario',
  'Veri' => 'Datos',
  'Eklenti silinirken tüm sohbetleri, mesajları ve medya dosyalarını da sil' => 'También elimine todos los chats, mensajes y archivos multimedia cuando se elimine el complemento.',
  'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.' => 'Los archivos multimedia se guardan en wp-content/uploads/flx-chat, cerrados al acceso externo. Se mueven con las cargas cuando se migra el sitio.',
