  'Karşılama mesajı' => 'Mensaje de bienvenida',
  'Bize ilk kez yazan kişiye otomatik gönder' => 'Enviar automáticamente a las personas que nos escriben por primera vez',
  'Mesai dışı yanıtı' => 'mensaje de ausencia',
  'Mesai saatleri dışında gelen mesajlara otomatik yanıt ver' => 'Respuesta automática a mensajes recibidos fuera del horario comercial',
  'Mesai günleri' => 'Días hábiles',
  'Başlangıç' => 'Empezar',
  'Bitiş' => 'Fin',
  'Aynı kişiye en fazla (saatte bir)' => 'Como máximo una vez por contacto cada (horas)',
  'Saat dilimi: %1$s. Şu an: %2$s.' => 'Zona horaria:%1$s. Ahora:%2$s.',
  'mesai içi' => 'dentro del horario comercial',
  'mesai dışı' => 'fuera del horario comercial',
  'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.' => 'En los textos se pueden utilizar las variables{first_name},{name},{brand},{site},{date}.',
  'Sohbet etiketleri' => 'Etiquetas de chat',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => 'Etiquete los chats y filtre la lista (por ejemplo, Donación, Queja, Seguimiento).',
  'Etiket ekle' => 'Agregar etiqueta',
  'Etiket adı' => 'Nombre de la etiqueta',
  'Sohbetten kayıt oluşturma' => 'Crear registros a partir de chats',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'Los botones en el encabezado del chat crean un registro de donación (Flux Donate) y un certificado (Certificados Flux), y un recibo entrante se compara con un registro. Si un complemento no está instalado, su botón está oculto.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'Los agentes pueden crear registros de donaciones y comparar recibos.',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'Los agentes pueden crear y enviar certificados.',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'Mostrar burbujas de respuesta rápida encima del cuadro de mensaje',
  'Bağış mesajları' => 'Mensajes de donación',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'Textos listos enviados a la persona cuando se crea un registro (editables antes de enviar). Si se deja vacío, se utiliza el texto predeterminado.',
  'Ödeme bekleniyor (havale sözü)' => 'En espera de pago (transferencia prometida)',
  'Bağış alındı' => 'Donación recibida',
  'Dekont onaylandı' => 'Recibo confirmado',
  'Banka bilgisi ({bank})' => 'Datos bancarios ({bank})',
  'Alıcı adı, banka, IBAN' => 'Nombre del destinatario, banco, IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'Si está vacía, se utiliza la cuenta en WooCommerce › Pagos › Transferencia bancaria.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variables:{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'Yapay zekâ bağlantısı' => 'Conexión de IA',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'Las claves, el almacenamiento en caché de avisos, los límites de gasto y los registros de uso provienen del complemento Flux AI & MCP; todas las solicitudes de IA del Call Center pasan por él. Las opciones de modelos se quedan aquí; si un campo está vacío, se utiliza el modelo elegido para este complemento en Flux AI (o el predeterminado).',
  'Flux AI ayarlarını aç' => 'Abrir la configuración de Flux AI',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'La IA necesita el complemento Flux AI y MCP. Instálelo y actívelo, luego ingrese la clave OpenRouter y/o Anthropic en Flux AI & MCP › Configuración. Hasta entonces quedan desactivadas las sugerencias, el asistente, la lectura de recibos, los mensajes de voz y los resúmenes.',
  'Yaratıcılık (0–1)' => 'Creatividad (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'Los valores más bajos dan respuestas más consistentes, los valores más altos, más libres. 0,4 recomendado.',
  'Model (öneriler için)' => 'Modelo (para sugerencias)',
  'Asistan modeli (isteğe bağlı)' => 'Modelo asistente (opcional)',
  'Yukarıdaki model' => 'Modelo arriba',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'Solo se enumeran los modelos que admiten herramientas.',
  'Dekont okuma modeli (isteğe bağlı)' => 'Modelo de lectura de recibos (opcional)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'Si el modelo seleccionado no puede leer imágenes, se utiliza automáticamente un modelo de visión económico.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'Este mes (%1$s): solicitudes%2$s, tokens%3$s, alrededor de $%4$s.',
  'Cevap önerisi' => 'Sugerencias de respuesta',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'Encima del cuadro de mensaje, se sugiere el siguiente mensaje de la conversación. El agente hace clic en "Enviar" o lo lleva al cuadro con "Editar". Una sugerencia nunca se envía sola.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'Preparar una sugerencia automáticamente cuando llegó el último mensaje de la persona (si está desactivado, pregunta con el botón ✨)',
  'Kurum bilgisi ve üslup' => 'Información y tono de la organización.',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'Por ej. Nuestra asociación planta árboles jóvenes en Estambul. La siembra se realiza todos los años entre noviembre y marzo. El certificado se envía por WhatsApp después de la donación. Utilice un tono cálido pero formal.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'Las sugerencias y el asistente utilizan esto. Los tipos de donación, precios, datos bancarios y respuestas rápidas se agregan automáticamente.',
  'Öneri sağlayıcısı' => 'Proveedor de sugerencias',
  'Bağış asistanı (otomatik cevap)' => 'Asistente de donaciones (respuestas automáticas)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'Cuando está activado, el asistente se responde a sí mismo: saluda, pregunta el nombre para dirigirse a ellos, envía opciones y precios de donación, opcionalmente recopila correo electrónico y "en nombre de quién", y pide confirmación después de cada cambio. Después de la confirmación, abre un registro "en espera de pago" en Flux Donate y envía el enlace de donación, el destinatario, el IBAN y la referencia como mensajes separados. Si el tema deja donaciones, entrega el chat al equipo.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'El complemento Flux Donate no está activo; el asistente no puede crear registros de donación.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'Instrucciones, documentos, chats de IA y chat de prueba.',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'Active el asistente de donación (desmarque para desactivarlo en todas partes)',
  'Hangi sohbetlerde cevap versin' => '¿A qué chats debería responder?',
  'Tüm sohbetlerde (önerilen)' => 'En todos los chats (recomendado)',
  'Temsilciye atanmamış sohbetlerde' => 'En chats no asignados a un agente',
  'Yalnız mesai saatleri dışında' => 'Sólo fuera del horario laboral',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'Cuando un agente escribe en un chat (desde el panel o el teléfono), el asistente se queda ahí callado el tiempo que aparece a continuación. Utilice el botón del asistente en el encabezado del chat para activarlo o desactivarlo por chat.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'Modo de prueba: responda solo a los números a continuación',
  'Test numaraları' => 'Números de prueba',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'Sepárelos con comas o líneas nuevas. No se utiliza cuando el modo de prueba está desactivado.',
  'Temsilci yazınca susma (saat)' => 'Silencio después de que un agente escribe (horas)',
  'Fiyat listesindeki adetler' => 'Cantidades en la lista de precios.',
  'Konuşma geçmişi (saat)' => 'Historial de conversaciones (horas)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'Antes de responder, el asistente lee todos los mensajes de este período.',
  'Asistanın sunduğu bağış türleri' => 'Tipos de donación que ofrece el asistente',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'Si no se selecciona ninguno, se ofrecen todos los tipos abiertos. Cuando se abre un nuevo tipo en Flux Donate, el asistente también lo sabe.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'Verificación previa del recibo: cuando el contacto envía un recibo, AI compara el monto, el destinatario y el IBAN con la donación, le informa al contacto el resultado, adjunta el archivo al registro de donación y entrega el chat al equipo para su aprobación final (no lo marca como pagado).',
  'Fiyat listesinin son satırı' => 'Última línea de la lista de precios.',
  'Ödeme bilgileri' => 'Detalles de pago',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'Si el destinatario y el IBAN están vacíos, se utilizan los de WooCommerce › Pagos › Transferencia bancaria (la cuenta que se muestra en los pedidos). Rellénelos sólo si el asistente debe usar una cuenta diferente.',
  'Alıcı adı' => 'Nombre del destinatario',
  'Havale açıklaması' => 'Descripción de la transferencia',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'Variables:{type},{name},{amount},{quantity}',
  'Bağış sayfası adresi' => 'URL de la página de donación',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'El tipo y la cantidad seleccionados se agregan al enlace (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'Mensaje después de los detalles de pago.',
  'Bağış iptali onay sorusu' => 'Pregunta de cancelación de donación.',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'El asistente cancela únicamente donaciones no pagadas, con la confirmación de la persona. Vacío = texto predeterminado. Variables:{bagis},{tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'Mensaje enviado cuando se alcanza el límite diario',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'Se envía una vez cuando un chat alcanza el límite de respuestas del día; el chat se entrega al equipo. Restablecerlo desde el menú ⋮ del chat › Uso del asistente.',
  'Ekibe devrederken gönderilen mesaj' => 'Mensaje enviado al momento de la entrega al equipo.',
  'Asistan cevap veremezse giden mesaj' => 'Mensaje enviado cuando el asistente no puede responder',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'Si la IA falla, se alcanza el límite de tiempo o la cola se vuelve demasiado larga, se envía este mensaje y el chat se entrega al equipo; la persona nunca se queda sin respuesta.',
  'Bekleme mesajından önce en az (sn)' => 'Espera mínima antes del mensaje(s) de espera',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'El mensaje en espera no se envía hasta tantos segundos después del mensaje de la persona; Mientras tanto el asistente vuelve a intentarlo.',
  'Bir cevabın en uzun süresi (sn)' => 'Mayor tiempo para una respuesta (s)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger puede reducir las solicitudes en ~60 s; Se recomienda 50.',
  'Devirde bildirim gidecek numaralar' => 'Números notificados en el traspaso',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'Cuando el asistente entrega un chat al equipo, desde la misma línea se envía un mensaje de WhatsApp a estos números: nombre del contacto, teléfono, motivo, últimos mensajes y enlace del panel. Sepárelos con comas o líneas nuevas. El asistente no habla con estos números.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'Cuando el contacto escribe uno de estos, el asistente envía inmediatamente el mensaje de transferencia anterior y se apaga en ese chat. Si se deja vacío, se utiliza la lista de ejemplo.',
  'Asistana ek talimatlar' => 'Instrucciones adicionales para el asistente.',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'Por ej. Se plantan árboles jóvenes en Kocaeli. Los certificados se envían una vez confirmada la donación.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'Último mensaje cuando un contacto se da de baja',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'Si alguien escribe algo como "no me envíes mensajes", el asistente envía este mensaje y lo incluye en la lista de bloqueo. Una persona incluida en la lista bloqueada no recibe WhatsApp, correo electrónico ni SMS; administre la lista en Chats › ☰ › Lista de bloqueo.',
  'Kişi hafızası ve arka plan işleri' => 'Memoria de contacto y trabajos en segundo plano.',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'Memoria de contacto: el asistente recuerda detalles duraderos (forma de dirección, nombres de familiares, números, preferencias); Se resumen los chats caducados.',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'Resumir un chat después de que haya estado en silencio durante (horas)',
  'Aynı anda en fazla iş' => 'Máximos trabajos al mismo tiempo',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'A cuántas personas se les puede responder al mismo tiempo. Las respuestas del asistente siempre son lo primero; los resúmenes no comienzan mientras alguien recibe respuesta o espera. Cada trabajo utiliza un trabajador PHP: en alojamiento compartido, manténgase por debajo de la mitad del límite total de trabajadores de sus sitios (por ejemplo, 20-30 de 60 trabajadores).',
  'Yalnız cevaplara ayrılan işçi' => 'Trabajadores reservados para respuestas.',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'Esta cantidad de trabajadores nunca toma resúmenes ni recordatorios.',
  'Özet saatleri' => 'Resumen de horas',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'Los resúmenes se publican únicamente entre estas horas (excepto un manual "Resumir ahora"). Si ambos son iguales, en cualquier momento.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'Cuando alguien envía un mensaje de voz, el asistente lo convierte en texto y responde (el texto también aparece en el panel como una línea del sistema)',
  'En uzun ses (sn)' => 'Mensaje de voz más largo (seg.)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'Para mensajes más largos, el asistente dice "el mensaje de voz fue demasiado largo para que podamos escucharlo".',
  'Sesli mesaj modeli (isteğe bağlı)' => 'Modelo de mensaje de voz (opcional)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'Modelo de audio económico (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'Debe ser un modelo de OpenRouter que acepte audio (Claude no). Se requiere una clave OpenRouter.',
  'Görseller' => 'Imágenes',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Deje que el asistente dibuje una imagen cuando sea útil (tabla, informe, diagrama); va a WhatsApp como una imagen, el texto se envía por separado',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'Se utiliza el renderizador de imágenes Flux AI (Flux AI y MCP › Configuración › Imágenes).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'No hay renderizador de imágenes en el servidor: ingrese una dirección de Gotenberg en Flux AI & MCP › Configuración › Imágenes o instale Imagick (SVG). Hasta entonces el asistente no dibuja imágenes.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Funciona una vez instalado Flux AI 0.2.0 o posterior.',
  'Başkası adına bağış' => 'Donación en nombre de alguien',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'Si la donación está a nombre de otra persona y se le dio su número (tarjeta de contacto o número tecleado), también enviar el certificado a ese número por WhatsApp una vez aprobado el pago.',
  'Sertifikadan önce giden mesaj' => 'Mensaje enviado antes del certificado.',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'Luego se envía el mensaje de certificado de WhatsApp de Flux Certificates. Variables:{ad},{bagisci},{bagis},{brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'Si una persona pregunta, el asistente configura un recordatorio (por ejemplo, "recuérdame cómo plantar un árbol cada mes", "envíame tus últimos proyectos cada mes", "pídeme un árbol cada mes"); cuando llega el momento, el asistente escribe y envía el mensaje',
  'Saat söylenmezse' => 'Cuando no se da tiempo',
  'Kişi başına en fazla' => 'Como máximo por persona',
  'Personel (Flux Roles)' => 'Personal (roles cambiantes)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Funciona una vez instalado Flux Roles 1.1.0: los usuarios cuyo número está configurado en Perfil › Número de WhatsApp obtienen herramientas de asistente adicionales según sus permisos.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'Darle al personal herramientas adicionales de asistente mediante permiso (donación en nombre de alguien con enlace de pago, mis donantes, informe general)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'Notificar al personal en WhatsApp cuando se paga o cancela una donación que ellos recomendaron.',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'Primer mensaje al donante para una donación abierta por el personal',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'Hola{ad}🌱 Se recibió tu solicitud de donación{bagis}a través de{personel}. Puedes pagar con los detalles a continuación.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'A continuación se muestran el enlace de pago y los datos bancarios. Variables:{ad},{adsoyad},{personel},{bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'Cuando se paga una donación referida por un miembro del personal y se emiten sus certificados, envíalos también al miembro del personal por WhatsApp (al igual que el donante)',
  'Personele sertifikadan önce giden mesaj' => 'Mensaje enviado al miembro del personal antes del certificado.',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variables:{ad},{bagisci},{bagis},{no},{brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => '¿Cuántas veces el personal puede reenviar el certificado de donación?',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'El asistente enumera los destinatarios y solicita confirmación antes de enviar. 0: apagado.',
  'Kayıt sorgusunda kod doğrulama' => 'Verificación de código para búsquedas de registros',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => 'Cuando una persona solicita sus registros y su número está oculto (o donó con otro número/correo electrónico), envíe un código al número o correo electrónico que proporcione; una vez verificado, sus registros también se muestran',
  'Kod geçerliliği (dk)' => 'Validez del código (min)',
  'En fazla başarısız deneme' => 'Máximo de intentos fallidos',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => 'Se cuentan los códigos que no se pudieron enviar, los códigos incorrectos y los códigos caducados. En el límite, la persona recibe el siguiente mensaje y se notifica al equipo; el asistente sigue respondiendo otras preguntas pero no comparte detalles del registro durante 24 horas.',
  'Telefona kod' => 'codigo al telefono',
  'WhatsApp, gitmezse SMS' => 'WhatsApp, SMS si falla',
  'Yalnız WhatsApp' => 'solo WhatsApp',
  'Yalnız SMS' => 'solo SMS',
  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => 'Se utiliza SMS si Flux Mail tiene una conexión SMS (por ejemplo, Netgsm).',
  'Doğrulama yapılamazsa giden mesaj' => 'Mensaje cuando falla la verificación',
  'WhatsApp/SMS kod mesajı' => 'Mensaje de código WhatsApp/SMS',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => 'Texto predeterminado si está vacío. Variables:{kod},{dk},{marka}. El texto del correo electrónico se edita en Flux Mail › Plantillas de correo electrónico.',
  'Sitedeki içerikler' => 'Contenido del sitio',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'Deje que el asistente busque contenido publicado en el sitio (por ejemplo, "¿tiene una publicación sobre plantación de árboles")',
  'Aranacak içerik türleri' => 'Tipos de contenido para buscar',
  'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.' => 'Sólo se devuelve el contenido publicado sin contraseña. Nunca se muestran borradores, contenido privado y protegido con contraseña.',
  'Hiç paylaşılmayacak kategori ve etiketler' => 'Categorías y etiquetas que nunca debes compartir',
  'ör. kurumsal-teklifler, ic-duyuru' => 'por ej. ofertas-corporativas, aviso-interno',
  'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.' => 'Nombre o slug, separados por comas. Para ocultar un solo elemento, marque "No permitir que el asistente comparta este contenido" en su pantalla de edición.',
  'Ekip grubu' => 'grupo de equipo',
  'WhatsApp grubu' => 'grupo whatsapp',
  '— Seçilmedi —' => '— No seleccionado —',
  'Hattın üye olduğu gruplar. Yeni açtığınız grup görünmüyorsa' => 'Grupos a los que pertenece la línea. Si falta un grupo que acaba de crear,',
  'listeyi yenileyin' => 'actualizar la lista',
  'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz' => 'Publicar mensajes entrantes y respuestas (asistente, equipo, automático) en este grupo',
  'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir' => 'Enviar notificaciones de transferencia a este grupo en lugar de a cada número; Los números anteriores se mencionan en el mensaje.',
  'Gruba son gönderim başarısız: ' => 'La última publicación del grupo falló:',
  'Fiyat listesi önizlemesi' => 'Vista previa de la lista de precios',
