  'Asistanın nasıl konuşacağını ve akışı anlatan ana metin. Fiyatlar, bağış türleri, banka bilgisi ve kişinin bilinen bilgileri her cevapta otomatik eklenir. {brand} kurum adına, {{belge:kisa-ad}} o belgenin içeriğine dönüşür.' => 'El texto principal describe cómo habla el asistente y el flujo. Los precios, los tipos de donación, los datos bancarios y lo que se sabe sobre el contacto se añaden automáticamente en cada respuesta.{brand}se convierte en el nombre de la organización y {{belge:kisa-ad}} se convierte en el contenido de ese documento.',
