  'Sık sorulan sorular, kampanya, dikim yerleri gibi bilgileri ayrı belgeler olarak ekleyin. Talimatta {{belge:kisa-ad}} yazarsanız belge oraya konur. "Gerektiğinde okur" seçilen belgeyi asistan yalnız konu açılınca okur; uzun belgeler için daha az maliyetlidir.' => 'Agregue preguntas frecuentes, campañas, lugares de plantación e información similar como documentos separados. Si escribe {{belge:kisa-ad}} en las instrucciones, el documento se coloca allí. Un documento configurado para "leer cuando sea necesario" sólo se lee cuando surge el tema, lo que cuesta menos para documentos largos.',
