  'Senaryolar test sohbetindeki gibi oynatılır: WhatsApp\'a mesaj gitmez, kayıt açılmaz. Model gerçekten çağrılır; ücret yapay zekâ hesabınızdan (OpenRouter ya da Anthropic) düşer ve limit dolunca çalıştırma durur.' => 'Los escenarios se reproducen como en el chat de prueba: no se envía ningún mensaje de WhatsApp y no se crea ningún registro. El modelo realmente se llama; el costo se carga a su cuenta de AI (OpenRouter o Anthropic) y la ejecución se detiene cuando se alcanza el límite.',
