  'Mesajlar (sırayla)' => 'Mensajes (en orden)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => 'Se pueden utilizar{tur},{birim}y{brand}. Si solo hay mensajes de clientes, el asistente responde a cada uno por turno. Si agrega mensajes del asistente, se convierte en un escenario de continuación: el historial escrito se proporciona tal cual y el asistente responde solo al último mensaje del cliente.',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => 'Por ej. información_pago, cancelar_donación, recibo_cheque. Las herramientas deshabilitadas en este sitio no están marcadas.',
  'Kim yazıyor?' => '¿Quién escribe?',
