  'Sonda durum' => 'Estado final',
  'Konuşma bitince test durumuna bakılır (bağış açıldı mı, iptal edildi mi, kod gitti mi…). Bu sitede kapalı araç bakılmaz.' => 'Cuando finaliza la conversación, se comprueba el estado de la prueba (si se abrió una donación, se canceló, se envió un código...). Las herramientas deshabilitadas en este sitio no están marcadas.',
