  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'Sigo usando el antiguo proveedor en Certificados Flux; mueva la conexión a Flux Mail y selecciónela aquí.',
  'Flux Certificates\'daki Evolution sağlayıcısı kullanılıyor.' => 'Utilizando el proveedor Evolution de Flux Certificates.',
  'API adresi, key ve instance bu eklentide girilmiş.' => 'La URL de API, la clave y la instancia se ingresan en este complemento.',
  '%s: hat durumu' => '%s: estado de la línea',
  'Telefon bağlı (son bilgi %s).' => 'Teléfono conectado (visto por última vez%s).',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'Aún no probado. Pulsa "Probar conexión".',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => 'Teléfono no conectado (estado:%1$s,%2$s). Vuelva a conectarse con "Conectar con QR".',
  '%s: Evolution API sürümü' => '%s: Versión de la API de evolución',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'La API de Evolution%sestá en uso. Las respuestas a contactos con números ocultos (@lid) pueden fallar; actualice el servidor a 2.3 o posterior.',
  '%s: webhook (gelen mesajlar)' => '%s: webhook (mensajes entrantes)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'No han llegado eventos de Evolution; Los mensajes entrantes no se mostrarán en el panel. Presione "Configurar webhook".',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'Llegó el último evento%s. Es posible que la línea esté simplemente en silencio; envíate un mensaje o configura el webhook nuevamente para estar seguro.',
  'Son olay %s geldi.' => 'Llegó el último evento%s.',
  'Flux Mail entegrasyonu' => 'Integración de correo Flux',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'Activo: Las conexiones de WhatsApp se toman desde Comunicación › Conexiones.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail no está activo; las conexiones se toman de Certificados Flux o de este complemento.',
  'Flux Certificates entegrasyonu' => 'Integración de certificados Flux',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'Activo: se pueden crear y enviar certificados desde los chats.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Los Certificados Flux no están activos; Las acciones de certificado en los chats están desactivadas.',
  'Flux Donate entegrasyonu' => 'Integración de donaciones de flujo',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'Activo: los registros de donaciones, el cotejo de recibos y el asistente están disponibles desde los chats.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donar no está activo; Los registros de donación, la comparación de recibos y el asistente de donación están desactivados.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'El complemento Flux AI & MCP no está instalado; Las funciones de IA (sugerencias, asistente, lectura de recibos, mensajes de voz, resúmenes) están desactivadas. Instale Flux AI e ingrese la clave allí.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'No se ha ingresado ninguna clave en Flux AI; las sugerencias de mensajes y el asistente están apagados.',
  'Anahtar var ama model seçilmemiş.' => 'Clave guardada pero no se seleccionó ningún modelo.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'No se ha ingresado ninguna clave de proveedor en Flux AI para el modelo seleccionado (%s).',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'Clave guardada, modelo:%s. Utilice "Probar conexión" para una verificación en vivo.',
  'Bağış asistanı' => 'asistente de donación',
  'Kapalı.' => 'Apagado.',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'Falta la clave o el modelo de IA.',
  'Açık ama konuşmuyor: ' => 'Encendido pero sin responder:',
  'Açık. Sunulan bağış türleri: %s.' => 'Encendido. Tipos de donación ofrecidos:%s.',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%sno admite herramientas; Elija un modelo con capacidad para herramientas para el asistente.',
  'Dekont okuma modeli' => 'Modelo de lectura de recibos',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%sno puede leer imágenes; la verificación previa del recibo no funcionará. Elija un modelo de lectura de recibos con capacidad de imagen.',
  'Asistanın ödeme bilgileri' => 'Detalles de pago del asistente',
  'Alıcı adı ve IBAN tanımlı.' => 'Nombre del destinatario y conjunto IBAN.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'Falta el nombre del destinatario o el IBAN; Los datos bancarios no se pueden enviar después de la confirmación.',
  'Bağış sayfası linki' => 'Enlace a la página de donaciones',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'Página de donación no encontrada; el asistente no enviará un enlace.',
  'Arka plan istekleri' => 'Solicitudes de antecedentes',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'El sitio no pudo enviarse una solicitud en segundo plano (%1$s:%2$s). Las respuestas en cola y el punto de referencia pueden moverse lentamente; un complemento de seguridad o el firewall del servidor pueden estar bloqueando las solicitudes /wp-json/flx-chat/.',
  'hata' => 'error',
  'uyarı' => 'advertencia',
  'tamam' => 'bien',
  '{marka} doğrulama kodunuz: {kod}' => 'Su código de verificación{marka}:{kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'El código es válido por minutos{dk}. Escríbelo en tu chat de WhatsApp con nosotros. Si no lo solicitaste, ignora este mensaje.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'Algo salió mal; nuestro equipo se pondrá en contacto contigo lo antes posible 🌱 Mientras tanto, no dudes en preguntar cualquier otra cosa.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'Intento de verificación fallido (%1$d/%2$d):%3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'La persona quería ver sus registros pero no pudo ser verificada; alguien del equipo debería ponerse en contacto',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'No se pudo enviar el correo electrónico (verifique Flux Mail › Configuración SMTP)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'El asistente envió un código de verificación para%1$s(%2$s).',
  'kodun süresi doldu' => 'código caducado',
  'yanlış kod' => 'código incorrecto',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'La persona verificó el código de%s; se agrega a sus búsquedas de registros.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'Los modelos Claude no pueden leer audio; elija un modelo OpenRouter con capacidad de audio en Configuración › AI › Modelo de mensaje de voz.',
  'Ses metne çevrilemedi.' => 'No se pudo transcribir el audio.',
  'Ses dosyası okunamadı.' => 'No se pudo leer el archivo de audio.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'Mensaje de voz (%1$s) transcrito:%2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'No se pudo procesar el mensaje de voz (%1$s):%2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'Esta acción no está disponible en una línea API oficial de WhatsApp Cloud.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'Regla de las 24 horas de WhatsApp: el contacto no ha escrito en las últimas 24 horas, por lo que la API de Cloud no enviará un mensaje de formato libre; sólo se puede enviar una plantilla aprobada. Inténtalo de nuevo una vez que escriban.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Una línea API de nube necesita Flux Mail 1.10.0 o posterior.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'La API de la nube no puede enviar a esta dirección (número o grupo oculto).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'No se pudo acceder a la cuenta API de la nube (İletişim › Conexiones).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Una línea de Cloud API no tiene código QR; la cuenta está configurada en İletişim › Conexiones.',
  'Dosya hazırlanamadı.' => 'No se pudo preparar el archivo.',
  'Flux AI görsel desteği yok.' => 'Flux AI no admite imágenes.',
  'Görsel çevrilemedi.' => 'No se pudo renderizar la imagen.',
  'Asistanın görseli gönderilemedi: ' => 'No se pudo enviar la imagen del asistente:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'Hola{first_name}, hemos creado tu registro de donación:{donation}, total{amount}.{bank}Después de pagar, puedes enviar el recibo aquí. Gracias.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'Hola{first_name}, tu donación ha quedado registrada:{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Gracias por su apoyo.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'El complemento que ejecutaría este escenario está inactivo.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'Este usuario no tiene permiso para utilizar las herramientas del personal.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$svinculó este chat con el miembro del personal%2$s',
  '%s sohbetin personel bağlantısını kaldırdı' => '%seliminó el enlace del personal de este chat.',
  'Sohbet personele bağlandı' => 'Chat vinculado a un miembro del personal',
  'Personel bağlantısı kaldırıldı' => 'Enlace de personal eliminado',
  '— Personel değil —' => '— No personal —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp oculta el número de esta persona, por lo que el asistente no puede reconocer al personal por número. Si esta persona está en su equipo, vincúlela aquí y el asistente abrirá las herramientas del personal.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'El asistente reconoce al personal por el número en su perfil de Flux Roles. Si el número no coincide, puedes vincularlos aquí; En un chat con un número conocido, el número es lo primero.',
  'Bu kanal şu an kullanılamıyor.' => 'Este canal no está disponible en este momento.',
  'Site sohbeti' => 'Chat del sitio',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'Todos los mensajes de WhatsApp, chat del sitio y otros canales aparecen aquí en vivo. Elige un chat a la izquierda.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => '[[\'Centro de llamadas de WhatsApp (Evolution API): vea mensajes entrantes y salientes en vivo, inicie un nuevo chat, respuestas predeterminadas, etiquetas, tareas, notas internas, respuestas automáticas; Registro de donación (Flux Donate) y certificado (Flux Certificates) desde el chat, cotejo de recibos. Sugerencia de respuesta de inteligencia artificial y asistente de donación automática con OpenRouter.\', \'tr\']]',
 ),
);
